//! Generic shapes for the CRUD resources under `/api/v1`.
//!
//! Every resource is a [`Record`] (server metadata plus the resource's data) and is
//! written with `PUT /api/v1/<resource>/{id}` using a [`Put`] body. Ids are UUIDv7s
//! generated by the client, so a retried PUT never creates a duplicate.

use serde::{Deserialize, Serialize};
use time::OffsetDateTime;
use uuid::Uuid;

/// Response header set to `1` when a PUT's `base_version` didn't match the stored
/// version. The write was still applied (last write wins).
pub const CONFLICT_HEADER: &str = "x-billo-conflict";

/// An amount in integer minor units (satang for THB) and an ISO 4217 code.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[cfg_attr(feature = "schema", derive(schemars::JsonSchema))]
pub struct Money {
    pub minor: i64,
    pub currency: String,
}

impl Money {
    pub fn new(minor: i64, currency: impl Into<String>) -> Self {
        Self {
            minor,
            currency: currency.into(),
        }
    }
}

/// A stored resource: metadata plus the resource's fields (flattened).
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[cfg_attr(feature = "schema", derive(schemars::JsonSchema))]
#[cfg_attr(feature = "schema", schemars(rename = "{D}Record"))]
pub struct Record<D> {
    pub id: Uuid,
    /// Starts at 1 and goes up on every write, including deletes.
    pub version: i64,
    #[serde(with = "time::serde::rfc3339")]
    #[cfg_attr(
        feature = "schema",
        schemars(with = "String", extend("format" = "date-time"))
    )]
    pub created_at: OffsetDateTime,
    #[serde(with = "time::serde::rfc3339")]
    #[cfg_attr(
        feature = "schema",
        schemars(with = "String", extend("format" = "date-time"))
    )]
    pub updated_at: OffsetDateTime,
    #[serde(flatten)]
    pub data: D,
}

/// Body of `PUT /api/v1/<resource>/{id}`: create, or update the record with this id.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[cfg_attr(feature = "schema", derive(schemars::JsonSchema))]
#[cfg_attr(feature = "schema", schemars(rename = "{D}Put"))]
pub struct Put<D> {
    /// The version the client last saw; omit when creating.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub base_version: Option<i64>,
    #[serde(flatten)]
    pub data: D,
}

/// Body of `GET /api/v1/<resource>`. An object (not a bare array) so paging can be
/// added later without breaking clients.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[cfg_attr(feature = "schema", derive(schemars::JsonSchema))]
#[cfg_attr(feature = "schema", schemars(rename = "{D}List"))]
pub struct List<D> {
    pub items: Vec<Record<D>>,
}
